from candidate import filter_by_prefix
from unittest import TestCase
from unittest.mock import patch

class TestFilterByPrefix(TestCase):

    def test_empty_input(self):
        self.assertEqual(filter_by_prefix([], 'a'), [])

    def test_no_prefix_match(self):
        self.assertEqual(filter_by_prefix(['abc', 'bcd', 'cde'], 'a'), [])

    def test_single_prefix_match(self):
        self.assertEqual(filter_by_prefix(['abc', 'a123', 'a456'], 'a'), ['abc', 'a123', 'a456'])

    def test_all_strings_match_prefix(self):
        self.assertEqual(filter_by_prefix(['a1', 'a2', 'a3'], 'a'), ['a1', 'a2', 'a3'])

    def test_non_string_input(self):
        with self.assertRaises(TypeError):
            filter_by_prefix([1, 'a', 2, 'b'], 'a')

    def test_invalid_input_type(self):
        with self.assertRaises(TypeError):
            filter_by_prefix('string', 123)

    def test_empty_string_prefix(self):
        self.assertEqual(filter_by_prefix(['abc', 'bcd', 'cde'], ''), [])

    def test_prefix_length_zero(self):
        self.assertEqual(filter_by_prefix(['abc', 'bcd', 'cde'], ''))
